mapper.select:
SELECT  FROM aftersales_case WHERE tenant_id=#{tenant} AND member_id=#{member} AND case_id>#{after}
    AND (LOCATE(#{filter.q},case_id)>0 OR LOCATE(#{filter.q},order_id)>0 OR LOCATE(#{filter.q},member_id)>0)
    AND status=#{filter.status} ORDER BY case_id LIMIT #{limit}

SELECT a.case_id,a.order_id,a.member_id,a.status,a.return_required,CAST(a.refund_amount AS CHAR) refund_amount,a.refund_id,a.version,a.items_json FROM aftersales_case a JOIN order_record o ON o.tenant_id=a.tenant_id AND o.order_id=a.order_id WHERE a.tenant_id=#{tenant}  AND a.case_id>#{after}
    AND (LOCATE(#{filter.q},a.case_id)>0 OR LOCATE(#{filter.q},a.order_id)>0 OR LOCATE(#{filter.q},a.member_id)>0 OR LOCATE(#{filter.q},a.refund_id)>0)
    AND a.status=#{filter.status} ORDER BY a.case_id LIMIT #{limit}
